    class wxBitmapBundleBuilder
    {
    public:
        wxVector<wxBitmap> m_bitmaps;

        void AddBitmap(const wxBitmap& bmp)
        {
            if (bmp.IsOk())
                m_bitmaps.push_back(bmp);
        }

        wxBitmapBundle Build()
        {
            if (m_bitmaps.empty())
                return wxBitmapBundle();
            return wxBitmapBundle::FromBitmaps(m_bitmaps);
        }
    };

